package com.clavis.reader;
import android.graphics.*;import android.graphics.drawable.Drawable;import android.text.*;
/** Original typographic jackets: no third-party cover artwork or network request. */
final class CatalogCover extends Drawable {
 final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);final TextPaint lettering=new TextPaint(Paint.ANTI_ALIAS_FLAG);final StaticLayout title,author;final int color;final boolean audio;int alpha=255;
 CatalogCover(String name,String writer,String id,Typeface typeface,boolean audio){this.audio=audio;int[] colors={0xffc9dfe4,0xffd9d0e6,0xffe7d6c5,0xffd0dfcf,0xffead1d8,0xffe1dfc6};color=colors[Math.floorMod(id.hashCode(),colors.length)];lettering.setTypeface(Typeface.create(typeface,Typeface.BOLD));lettering.setTextSize(name.length()>45?31:38);lettering.setColor(0xff30353c);title=StaticLayout.Builder.obtain(name,0,name.length(),lettering,228).setAlignment(Layout.Alignment.ALIGN_CENTER).setIncludePad(false).setMaxLines(5).setEllipsize(TextUtils.TruncateAt.END).build();TextPaint byline=new TextPaint(lettering);byline.setTypeface(typeface);byline.setTextSize(19);author=StaticLayout.Builder.obtain(writer,0,writer.length(),byline,224).setAlignment(Layout.Alignment.ALIGN_CENTER).setIncludePad(false).setMaxLines(2).setEllipsize(TextUtils.TruncateAt.END).build();}
 @Override public void draw(Canvas c){Rect b=getBounds();c.save();c.translate(b.left,b.top);c.scale(b.width()/300f,b.height()/420f);int layer=c.saveLayerAlpha(0,0,300,420,alpha);paint.setStyle(Paint.Style.FILL);paint.setColor(color);c.drawRoundRect(0,0,300,420,12,12,paint);paint.setColor(0x1830353c);c.drawRect(0,0,19,420,paint);paint.setColor(0x66ffffff);c.drawLine(23,12,23,408,paint);paint.setColor(0xff56616b);paint.setStrokeWidth(2);c.drawLine(70,60,248,60,paint);c.drawLine(70,69,248,69,paint);c.save();c.translate(45,100);title.draw(c);c.restore();c.save();c.translate(47,318);author.draw(c);c.restore();paint.setColor(0xff56616b);c.drawLine(115,378,203,378,paint);if(audio){Path play=new Path();play.moveTo(148,386);play.lineTo(148,406);play.lineTo(167,396);play.close();c.drawPath(play,paint);}else{c.drawCircle(158,396,5,paint);}c.restoreToCount(layer);c.restore();}
 @Override public void setAlpha(int value){alpha=value;invalidateSelf();}
 @Override public void setColorFilter(ColorFilter filter){paint.setColorFilter(filter);lettering.setColorFilter(filter);invalidateSelf();}
 @Override public int getOpacity(){return PixelFormat.TRANSLUCENT;}
}
